function validate([edges, k]) {
  const n = edges.length + 1;
  if (n < 2 || n > 100000) return 'The tree needs 2 to 10^5 nodes, so 1 to 10^5 - 1 edges.';
  if (k < 1 || k > n - 1) return 'k is between 1 and n - 1.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (edge.length !== 3) return 'Each edge is [u, v, w].';
    const [u, v, w] = edge;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge endpoints are nodes 0 to n - 1.';
    if (w < 1 || w > 1e6) return 'Each weight is between 1 and 10^6.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree: no loops, cycles or repeated edges.';
    root[a] = b;
  }
  return null;
}

