function maximizeSumOfWeights(edges, k) {
  const n = edges.length + 1;
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    graph[u].push([v, w]);
    graph[v].push([u, w]);
  }

  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const [next] of graph[node]) {
      if (next === parent[node]) continue;
      parent[next] = node;
      order.push(next);
    }
  }

  const keep = new Array(n).fill(0);
  const drop = new Array(n).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    let base = 0;
    const gains = [];
    for (const [child, weight] of graph[node]) {
      if (child === parent[node]) continue;
      base += drop[child];
      const gain = keep[child] + weight - drop[child];
      if (gain > 0) gains.push(gain);
    }
    gains.sort((a, b) => b - a);
    let best = base;
    for (let j = 0; j < k - 1 && j < gains.length; j++) {
      best += gains[j];
    }
    keep[node] = best;
    drop[node] = gains.length >= k ? best + gains[k - 1] : best;
  }
  return drop[0];
}

