function maximizeSumOfWeights(edges, k) {
  // Try every subset of edges and keep the heaviest one whose degrees all stay within k.
  let best = 0;
  for (let mask = 0; mask < (1 << edges.length); mask++) {
    const degree = {};
    let sum = 0;
    let fits = true;
    edges.forEach(([u, v, w], i) => {
      if ((mask >> i & 1) === 0) return;
      degree[u] = (degree[u] || 0) + 1;
      degree[v] = (degree[v] || 0) + 1;
      if (degree[u] > k || degree[v] > k) fits = false;
      sum += w;
    });
    if (fits && sum > best) best = sum;
  }
  return best;
}

