function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2001 : 2 + pick(10);
  // Shapes: 0 random, 1 path, 2 a few hubs (stars), 3 a caterpillar along a spine.
  const shape = pick(4);
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
  const top = large ? 1e6 : [1, 3, 10, 1e6][pick(4)];
  const edges = [];
  for (let i = 1; i < n; i++) {
    const p = shape === 0 ? pick(i) : shape === 1 ? i - 1 : shape === 2 ? pick(Math.min(i, 3)) : Math.max(0, i - 1 - pick(3));
    const w = 1 + pick(top);
    edges.push(rand() < 0.5 ? [label[i], label[p], w] : [label[p], label[i], w]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const k = 1 + pick(large ? 4 : n - 1);
  return [edges, k];
}
